// smartcontracts/vectors/ua/groups.json (UA-2c, generated by clients/ua-rs tests/groups.rs from k256 / ZF frost-core), read by
// the verifiers of src/ua-group.js (noble, written from accounts.md §1.6.1 / RFC 9591 / frost-core's DKG, not from the generator)
// for all four group kinds: every group's PoP and signatures accepted, every negative refused for its stated reason, the same rows
// and verdicts as ua-rs tests/groups_verify.rs (so the two agree row by row), the records and msig slots through
// src/ua-verify.js, one-change negatives with their positive control; the secp256k1 KeyAgg / DKG values recomputed here, the
// official BIP-327 KeyAgg rows, RFC 9591 E.5, the ZF DKG vector and T-FROST. musig2-bn254 and frost-bn254 have no independent
// second implementation (single-implementation kinds, accounts.md §1.16): ua-rs and clientkeys agreeing on them is
// self-consistency only. UNAUDITED.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dir } from "./ua-vectors-dir.js";
import { secp256k1, schnorr } from "@noble/curves/secp256k1.js";
import { bn254 } from "@noble/curves/bn254.js";
import { hash_to_field } from "@noble/curves/abstract/hash-to-curve.js";
import { sha256 } from "@noble/hashes/sha2.js";
import * as ua from "../src/ua.js";
import * as uv from "../src/ua-verify.js";
import { hex, fromHex, concatBytes, utf8ToBytes, word } from "../src/bytes.js";

const V = JSON.parse(readFileSync(new URL("groups.json", dir)));
const Pt = secp256k1.Point;
const N = Pt.Fn.ORDER;
const G = Pt.BASE;
const B = (h) => fromHex(h);
const int = (b) => BigInt(hex(b));
const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);
const attempt = (f) => {
  try {
    return f();
  } catch {
    return false;
  }
};
const u16 = (d, o) => (d[o] << 8) | d[o + 1];
const mul = (P, k) => P.multiplyUnsafe(((k % N) + N) % N);
const tagged = (tag, ...parts) => {
  const t = sha256(utf8ToBytes(tag));
  return sha256(concatBytes(t, t, ...parts));
};
/** SEC1 compressed, prefix 02/03 only. */
const point = (b) => {
  if (b.length !== 33 || (b[0] !== 2 && b[0] !== 3)) throw new Error("prefix");
  return Pt.fromBytes(b);
};
const enc = (P) => (P.equals(Pt.ZERO) ? new Uint8Array(33) : P.toBytes(true));
/** RFC 9591 §6.5: hash_to_field, expand_message_xmd SHA-256, DST "FROST-secp256k1-SHA256-v1" ‖ label, 48 bytes, mod N. */
const H = (label, m) =>
  hash_to_field(m, 1, {
    DST: utf8ToBytes(`FROST-secp256k1-SHA256-v1${label}`),
    p: N,
    m: 1,
    k: 128,
    expand: "xmd",
    hash: sha256,
  })[0][0];

// --- musig2-secp256k1 (BIP-327 KeyAgg, §1.6.1) ---
function keyAgg(pks) {
  const L = tagged("KeyAgg list", ...pks);
  const second = pks.find((p) => !eq(p, pks[0]));
  const a = pks.map((p) => (second && eq(p, second) ? 1n : int(tagged("KeyAgg coefficient", L, p)) % N));
  const Q = pks.reduce((acc, p, i) => acc.add(mul(point(p), a[i])), Pt.ZERO);
  return { L, a, Q };
}
const members = (kd) => Array.from({ length: u16(kd, 33) }, (_, i) => kd.subarray(35 + 33 * i, 68 + 33 * i));

// --- frost-secp256k1 (frost-core DKG), the ZF vector's second check ---
/** frost-core keys::dkg: c_i = HDKG(id_i (32 B) ‖ C_i0 ‖ R_i), R_i == μ_i·G − c_i·C_i0; Y == Σ C_i0, refusing a C_i0 that
 *  shares its x with the partial sum (repeated or cancelling: FrostSecp256k1Verifier's mixed addition refuses it). */
function frostDkg(kd) {
  const t = u16(kd, 33),
    n = u16(kd, 35),
    per = (t + 1) * 33 + 32;
  let S = Pt.ZERO;
  for (let i = 0; i < n; i++) {
    const b = kd.subarray(37 + i * per, 37 + (i + 1) * per);
    const C0 = b.subarray(0, 33),
      R = b.subarray(t * 33, (t + 1) * 33);
    const c = H("dkg", concatBytes(word(i + 1), C0, R));
    if (!point(R).equals(mul(G, int(b.subarray((t + 1) * 33))).subtract(mul(point(C0), c)))) return false;
    if (i > 0 && S.x === point(C0).x) return false;
    S = S.add(point(C0));
  }
  return eq(enc(S), kd.subarray(0, 33));
}

const SECP = [0x0110, 0x0111];
const valid = (kind, kd) => attempt(() => (ua.validateKeyData(kind, kd), true));
// the library's verifiers (src/ua-verify.js → src/ua-group.js): `verifyPop` on key data, `verify` on the stored vk
const verifyPop = (kind, kd, msg, pop) => uv.verify(kind, hex(kd), hex(msg), hex(pop), true);
const verify = (kind, vk, msg, sig) => uv.verify(kind, hex(vk), hex(msg), hex(sig), false);
const frostVerify = (Y, msg, sig) => verify(0x0111, Y, msg, sig);
const vkLen = (kind) => (SECP.includes(kind) ? 33 : 64);
// groups.json is written by clients/ua-rs (tests/groups.rs): the PoPs are portable typed records (UA-8 P1, typed-signing
// TS-D1 / TS-D3): popDigest = portableRecordDigest (UAPortableRecord{ua, kind, 0, UAKemRecord{ua, 0, 0, 0}}), message =
// uaMessage(kind, POP_V2, registrationDigest); contexts.A only serves the chain-bound negative (pop-chain-bound).
const popMsg = (kind, kd) => {
  const words = { ua: ua.uaOf(kind, kd), kind };
  return [ua.portableRecordDigest(words), ua.uaMessage(kind, ua.POP_V2_TAG, ua.registrationDigest(words))];
};

test("groups: ids, secp256k1 KeyAgg / DKG recomputed, PoP and signatures verify (all four kinds)", () => {
  assert.equal(V.groups.length, 20);
  for (const g of V.groups) {
    const kd = B(g.keyData);
    assert.equal(hex(ua.deriveUA(g.kind, kd)), g.ua, g.name);
    assert.equal(hex(ua.keyHashOf(g.kind, kd)), g.keyHash, g.name);
    assert.equal(g.vk, hex(kd.subarray(0, vkLen(g.kind))), g.name);
    const [d, m] = popMsg(g.kind, kd);
    assert.deepEqual([hex(d), hex(m)], [g.pop.popDigest, g.pop.message], g.name);
    if (g.kind === 0x0110) {
      const pks = members(kd);
      const { L, a, Q } = keyAgg(pks);
      assert.equal(hex(enc(Q)), g.vk, `${g.name}: Q`);
      assert.equal(hex(L), g.L);
      assert.deepEqual(
        a.map((x) => hex(word(x))),
        g.coefficients,
      );
      assert.deepEqual(
        pks.map((p, i) => hex(mul(point(p), a[i]).toBytes(false).subarray(1))),
        g.hints,
      );
      assert.equal(g.pop.blob, hex(concatBytes(B(g.pop.sig), ...g.hints.map(B))));
    } else if (g.kind === 0x0111) {
      for (const r of g.dkg) {
        const pre = concatBytes(word(r.id), B(r.commitments[0]), B(r.R));
        assert.equal(hex(pre), r.preimage);
        assert.equal(hex(word(H("dkg", pre))), r.challenge, `${g.name} participant ${r.id}`);
      }
      assert.equal(g.pop.blob, g.pop.sig);
    }
    assert.ok(verifyPop(g.kind, kd, m, B(g.pop.blob)), `${g.name}: verifyPop`);
    assert.ok(verify(g.kind, kd.subarray(0, vkLen(g.kind)), m, B(g.pop.sig)), `${g.name}: PoP sig against vk`);
    for (const s of g.sigs) {
      const mm = ua.uaMessage(g.kind, ua.purposeTag(s.purpose), B(s.digest));
      assert.equal(hex(mm), s.message);
      assert.ok(verify(g.kind, B(g.vk), mm, B(s.sig)), `${g.name} ${s.purpose}`);
    }
  }
});

test("every negative refused for its stated reason (all four kinds; the rows ua-rs groups_verify.rs refuses)", () => {
  let n = 0;
  for (const g of V.groups)
    for (const x of g.negatives) {
      const name = `${g.name} ${x.name}`;
      if (x.entry === "verify") {
        assert.equal(verify(g.kind, B(x.vk), B(x.message), B(x.sig)), false, name);
      } else {
        const kd = B(x.keyData);
        const [, m] = popMsg(g.kind, kd);
        assert.deepEqual([hex(ua.uaOf(g.kind, kd)), hex(m)], [x.ua, x.message], name);
        const pop = B(x.pop);
        const sig = pop.subarray(0, { 0x0110: 64, 0x0111: 65 }[g.kind] ?? 96);
        assert.equal(verify(g.kind, kd.subarray(0, vkLen(g.kind)), m, sig), x.sigValid, `${name}: sigValid`);
        // verifyPop validates the key data itself (ua-rs `verify` with pop, the registry's `validateKeyData` before it)
        if (x.error === "UAKeyData") assert.ok(!valid(g.kind, kd) && !verifyPop(g.kind, kd, m, pop), name);
        else assert.ok(x.error === "UAPoP" && valid(g.kind, kd) && !verifyPop(g.kind, kd, m, pop), name);
      }
      n++;
    }
  assert.equal(n, 98);
});

test("BIP-327 KeyAgg rows (official, incl. duplicate and unsorted lists)", () => {
  assert.equal(V.bip327.keyAgg.length, 4);
  for (const r of V.bip327.keyAgg) {
    const { L, a, Q } = keyAgg(r.keys.map(B));
    assert.equal(hex(enc(Q)), r.Q);
    assert.equal(hex(enc(Q).subarray(1)), r.expectedX.toLowerCase());
    assert.equal(hex(L), r.L);
    assert.deepEqual(
      a.map((x) => hex(word(x))),
      r.coefficients,
    );
    assert.deepEqual(
      r.keys.map((k, i) =>
        hex(
          mul(point(B(k)), a[i])
            .toBytes(false)
            .subarray(1),
        ),
      ),
      r.hints,
    );
  }
  // and the official file's expected keys directly
  const o = V.bip327.official.key_agg_vectors;
  for (const c of o.valid_test_cases)
    assert.equal(
      hex(enc(keyAgg(c.key_indices.map((i) => B(o.pubkeys[i]))).Q).subarray(1)),
      `0x${c.expected.toLowerCase()}`,
    );
});

test("RFC 9591 E.5, the ZF DKG vector, T-FROST", () => {
  const e = V.rfc9591E5;
  assert.ok(frostVerify(B(e.groupPublicKey), B(e.message), B(e.sig)));
  assert.equal(hex(mul(G, int(B(e.groupSecretKey))).toBytes(true)), e.groupPublicKey);
  assert.ok(valid(0x0111, B(V.zfDkg.keyData)) && frostDkg(B(V.zfDkg.keyData)));
  assert.equal(V.tFrost.length, 10);
  for (const r of V.tFrost) {
    const ok =
      r.verifier === "bip340"
        ? attempt(() => schnorr.verify(B(r.sig), B(r.message), B(r.key)))
        : attempt(() => frostVerify(B(r.key), B(r.message), B(r.sig)));
    assert.equal(ok, r.valid, r.name);
  }
});

// T21 L20: group kinds as msig members (groups.json msigMembers, written by ua-rs; ua-rs tests/groups.rs msig_group_members gives the
// same verdicts). The msig id and member digest are recomputed with ua.js; each group slot is checked as the registry checks a member:
// against its stored vk (the key data's head), pop false; verifyAuthorization accepts "all five" and refuses each changed slot.
test("group kinds as msig members: id, member digest, every group slot; verifyAuthorization's verdict per row", () => {
  const { verifyAuthorization } = uv;
  const v = V.msigMembers;
  const kd = B(v.keyData);
  assert.equal(hex(ua.uaOf(0x0120, kd)), v.ua);
  const md = ua.memberDigest(B(v.ua), ua.uaMessage(0x0120, B(v.purposeTag), B(v.digest)));
  assert.equal(hex(md), v.memberDigest);
  const st = ua.msigStructure(kd);
  assert.deepEqual(
    st.members.map((m) => m.kind),
    v.members.map((m) => m.kind),
  );
  const byId = (id) => v.members.find((m) => m.ua === id);
  const mm = (kind) => ua.uaMessage(kind, ua.purposeTag("member"), md);
  let n = 0;
  for (const row of [...v.authorizations, ...v.negatives]) {
    for (const s of row.slots) {
      const m = byId(st.members[s.index].id);
      if (m.kind < 0x0110 || m.kind > 0x0113) continue;
      const ok = verify(m.kind, B(m.keyData).subarray(0, vkLen(m.kind)), mm(m.kind), B(s.sig));
      const changed = !row.valid && row.name.startsWith(`slot ${s.index} `);
      assert.equal(ok, !changed, `${row.name}: slot ${s.index}`);
      n++;
    }
    const members = (id) => {
      if (id === v.ua) return { kind: 0x0120, keyData: v.keyData };
      const m = byId(id);
      return m && m.kind !== 1 ? { kind: m.kind, keyData: m.keyData } : undefined;
    };
    const domain = { generation: 1, ...V.contexts.A };
    const judge = () =>
      verifyAuthorization(
        { ua: v.ua, purposeTag: v.purposeTag, digest: v.digest, sig: row.uaSig },
        members,
        domain,
        () => true,
      );
    if (row.valid) judge();
    else assert.throws(judge, { code: "UAUnauthorized" }, row.name);
  }
  assert.equal(n, 24);
});

// bls-multi T4: groups.json blsMulti (written by clients/ua-rs tests/groups.rs, checked here on noble): the H_G1 KATs under both DSTs,
// every group's id, stored form, popMsg and pop, every PoP row and every signature row (verify and verifyMinimal) as written.
test("bls_multi: groups.json blsMulti rows", async () => {
  const bm = await import("../src/bls-multi.js");
  const { verify } = await import("../src/ua-verify.js");
  const { bls12_381 } = await import("@noble/curves/bls12-381.js");
  const s = V.blsMulti;
  assert.deepEqual([s.dsts.sig, s.dsts.pop], [bm.DST_MULTI_SIG, bm.DST_MULTI_POP]);
  for (const r of s.hashToG1) {
    const P = bls12_381.G1.hashToCurve(B(r.msg), { DST: r.dst === "sig" ? bm.DST_MULTI_SIG : bm.DST_MULTI_POP });
    assert.equal(hex(bm.g1Bytes(P)), r.point);
  }
  for (const g of s.groups) {
    assert.equal(hex(ua.deriveUA(0x0121, B(g.keyData))), g.ua, g.name);
    assert.equal(hex(bm.storedBlsMulti(g.keyData)), g.stored, g.name);
    assert.equal(hex(bm.popMessage(g.keyData)), g.popMessage, g.name);
    assert.ok(verify(0x0121, g.keyData, g.popMessage, g.pop, true), g.name);
  }
  for (const r of s.pop) {
    assert.equal(hex(bm.popMessage(r.keyData)), r.popMessage, r.name);
    assert.equal(verify(0x0121, r.keyData, r.popMessage, r.pop, true), r.valid, r.name);
  }
  for (const r of s.signatures) {
    assert.equal(hex(bm.storedBlsMulti(r.keyData)), r.stored, r.name);
    assert.equal(verify(0x0121, r.keyData, r.uaMsg, r.signature, false, false), r.verify, r.name);
    assert.equal(verify(0x0121, r.keyData, r.uaMsg, r.signature, false, true), r.minimal, r.name);
  }
  assert.deepEqual([s.pop.length, s.signatures.length], [11, 30]);
});

// bls-multi T15: groups.json blsMulti.wallet: the 0x0121 member keys of keys.json's mnemonic derived here (uakey.js, EIP-2333),
// each member's partial and PoP part signed here on noble, the minimal aggregate and the PoP: what every binding reproduces.
test("bls_multi: groups.json blsMulti.wallet parts", async () => {
  const bm = await import("../src/bls-multi.js");
  const { verify } = await import("../src/ua-verify.js");
  const { deriveUAKey } = await import("../src/uakey.js");
  const { seedFromWords } = await import("../src/seed.js");
  const w = V.blsMulti.wallet;
  const m = JSON.parse(readFileSync(new URL("keys.json", dir))).mnemonics.find((x) => x.id === w.mnemonic);
  const seed = seedFromWords(m.words, m.passphrase);
  const keys = w.members.map((r) => deriveUAKey(seed, { kind: w.kind, account: r.account, index: w.index }));
  assert.deepEqual(
    keys.map((k) => hex(k.keyData)),
    w.members.map((r) => r.key),
  );
  const { keyData, indexMap } = bm.buildKeyData(
    keys.map((k, i) => ({ key: k.keyData, weight: w.members[i].weight })),
    w.threshold,
  );
  assert.equal(hex(keyData), w.keyData);
  assert.deepEqual(
    indexMap,
    w.members.map((r) => r.keyDataIndex),
  );
  keys.forEach((k, i) => {
    assert.equal(hex(k.signBlsMulti(B(w.keyData), B(w.uaMsg))), w.members[i].partial);
    assert.equal(hex(k.signBlsMultiPop(B(w.keyData))), w.members[i].popPart);
  });
  const parts = (f) => w.members.map((r) => [r.keyDataIndex, B(r[f])]);
  const agg = bm.aggregate(w.keyData, w.uaMsg, parts("partial"));
  assert.deepEqual([hex(agg.signature), agg.signers], [w.signature, w.signers]);
  assert.ok(verify(0x0121, w.keyData, w.uaMsg, hex(bm.blsMultiAbi(agg)), false, true));
  assert.equal(hex(bm.aggregatePop(w.keyData, parts("popPart"))), w.pop);
  assert.ok(verify(0x0121, w.keyData, w.popMessage, w.pop, true));
});

// A group UA's own portable record (requirePortable → `_single` → verifyPop on its key data, as the tree reader's signer check
// reaches it through verifyPortable): the main groups' metatx signature, for musig2-secp256k1 followed by its hints; a byte off, a
// hint off, or the bare signature where the hints belong: UAUnauthorized.
test("a group UA's portable record: verifyPop over its key data, refused one change off", () => {
  const main = V.groups.filter((g) => g.role === "main");
  assert.equal(main.length, 4);
  for (const g of main) {
    const s = g.sigs.find((x) => x.purpose === "metatx");
    const members = (id) => (id === g.ua ? { kind: g.kind, keyData: g.keyData } : undefined);
    const hints = g.kind === 0x0110 ? concatBytes(...g.hints.map(B)) : new Uint8Array(0);
    const row = (sig, digest = s.digest) => ({ ua: g.ua, purpose: s.purposeTag, digest, sig: hex(sig) });
    const good = concatBytes(B(s.sig), hints);
    uv.verifyPortable(row(good), members);
    const off = (b, i) => {
      const c = b.slice();
      c[i] ^= 1;
      return c;
    };
    const refused = (r, what) =>
      assert.throws(() => uv.verifyPortable(r, members), { code: "UAUnauthorized" }, `${g.name}: ${what}`);
    refused(row(off(good, 10)), "signature byte");
    refused(row(good, hex(off(B(s.digest), 0))), "digest");
    if (g.kind === 0x0110) {
      refused(row(off(good, 64 + 5)), "hint byte");
      refused(row(B(s.sig)), "no hints");
    }
  }
});

// One change at a time to a signature that verifies (the positive control first): wrong message, wrong key, s / z at or above the
// order, R off the curve, R non-canonical (bn254), wrong length, the other group kind's message, the key data's head as vk changed.
test("verify: one-change negatives with their positive control (all four kinds)", () => {
  const ORDER = { 0x0110: N, 0x0111: N, 0x0112: bn254.fields.Fr.ORDER, 0x0113: bn254.fields.Fr.ORDER };
  const other = { 0x0110: 0x0111, 0x0111: 0x0110, 0x0112: 0x0113, 0x0113: 0x0112 };
  for (const g of V.groups.filter((x) => x.role === "main")) {
    const s = g.sigs.find((x) => x.purpose === "metatx");
    const [vk, msg, sig] = [B(g.vk), B(s.message), B(s.sig)];
    const no = (k, m, x, what) => assert.equal(verify(g.kind, k, m, x), false, `${g.name}: ${what}`);
    assert.ok(verify(g.kind, vk, msg, sig), `${g.name}: control`);
    const w = sig.length - 32;
    const z = int(sig.subarray(w));
    const withZ = (v) => concatBytes(sig.subarray(0, w), word(v));
    no(vk, B(hex(msg).replace(/.$/, (c) => (parseInt(c, 16) ^ 1).toString(16))), sig, "message");
    const otherVk = B(V.groups.find((x) => x.kind === g.kind && x.role !== "main").vk);
    no(otherVk, msg, sig, "another group's vk");
    no(vk, msg, withZ(ORDER[g.kind]), "s = order");
    if (z + ORDER[g.kind] < 1n << 256n) no(vk, msg, withZ(z + ORDER[g.kind]), "s + order");
    no(vk, msg, concatBytes(sig, Uint8Array.of(0)), "a byte appended");
    no(vk, msg, sig.subarray(0, sig.length - 1), "a byte short");
    no(vk, ua.uaMessage(other[g.kind], ua.purposeTag("metatx"), B(s.digest)), sig, "the other kind's message");
    no(B(g.keyData), msg, sig, "the whole key data as vk");
    if (g.kind === 0x0111) no(vk, msg, concatBytes(Uint8Array.of(sig[0] ^ 1), sig.subarray(1)), "R's parity");
    if (g.kind >= 0x0112) {
      const Rx = int(sig.subarray(0, 32));
      no(vk, msg, concatBytes(word(Rx + bn254.fields.Fp.ORDER), sig.subarray(32)), "x(R) + p");
      no(vk, msg, concatBytes(word(1n), word(3n), sig.subarray(64)), "R off the curve");
      no(concatBytes(word(1n), word(3n)), msg, sig, "vk off the curve");
    } else {
      no(concatBytes(Uint8Array.of(4), vk.subarray(1)), msg, sig, "vk prefix 04");
    }
    // secp256k1: BIP-340 and RFC 9591 do not stand in for each other (accounts.md §1.6.1); the bn254 kinds' `verify` is the same scaas
    // Schnorr, kept apart by the kind in `ua_msg` (the other kind's message above)
    assert.equal(
      uv.verify(other[g.kind], hex(vk), hex(msg), hex(sig), false),
      g.kind >= 0x0112,
      `${g.name}: under the other kind`,
    );
  }
  // musig2-secp256k1 verifies by x(Q) alone (Musig2Secp256k1Verifier: Q's parity plays no role): the negated vk is accepted
  const g = V.groups.find((x) => x.kind === 0x0110 && x.role === "main");
  const s = g.sigs.find((x) => x.purpose === "metatx");
  const neg = B(g.vk).slice();
  neg[0] ^= 1;
  assert.ok(verify(0x0110, neg, B(s.message), B(s.sig)));
});
